/* Generated by agent/tools/prepare_calib.py (v1) — do not edit by hand.
 * CALIBRATION benchmark: used only to tune the agent's per-region budget (decision D3),
 * never in an experiment and never in a reported result.
 *
 * A genuine prefix-sum recurrence: element i needs element i-1. The correct answers are to decline, or to rewrite it as a two-pass scan. It gives the attempt distribution a tail — without it every region would be easy.
 *
 * Default dataset SMALL; override with -D<SIZE>_DATASET.
 * Prints a value digest to stdout; -DPB_FULL_DUMP prints every value. */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>

#if !defined(MINI_DATASET) && !defined(SMALL_DATASET) && !defined(STANDARD_DATASET) \
    && !defined(LARGE_DATASET) && !defined(EXTRALARGE_DATASET)
# define SMALL_DATASET
#endif
#ifdef MINI_DATASET
# define N 1000
#endif
#ifdef SMALL_DATASET
# define N 1000000
#endif
#ifdef STANDARD_DATASET
# define N 10000000
#endif
#ifdef LARGE_DATASET
# define N 30000000
#endif
#ifdef EXTRALARGE_DATASET
# define N 60000000
#endif

#define R 4

/* ---- output: digest by default, full dump with -DPB_FULL_DUMP ------------ */
#ifdef PB_FULL_DUMP
# define pb_emit(v) fprintf(stdout, "%0.17g\n", (double)(v))
# define pb_report() ((void)0)
#else
static unsigned long long pb_count = 0;
static double pb_sum = 0.0;
static double pb_wsum = 0.0;
static void pb_emit(double v)
{
  pb_count++;
  pb_sum += v;
  pb_wsum += v * (double)((pb_count % 9973) + 1);
}
static void pb_report(void)
{
  printf("pb_values %llu\n", pb_count);
  printf("pb_sum %.17g\n", pb_sum);
  printf("pb_wsum %.17g\n", pb_wsum);
}
#endif

/* ---- optional perturbed input: argv[1] = seed ---------------------------- */
static unsigned long long pb_seed(const char* s)
{
  return strtoull(s, NULL, 10) * 0x9E3779B97F4A7C15ULL + 1ULL;
}
static double pb_uniform(unsigned long long* state)
{
  *state = *state * 6364136223846793005ULL + 1442695040888963407ULL;
  return (double)(*state >> 11) / 9007199254740992.0;
}
#define PB_PERTURB(arr, count)                                              \
  do {                                                                      \
    double* pb_p = (double*)(arr);                                          \
    unsigned long long pb_k, pb_n = (unsigned long long)(count);            \
    for (pb_k = 0; pb_k < pb_n; pb_k++)                                     \
      pb_p[pb_k] += (double)(pb_uniform(&pb_state) * 3.0);                  \
  } while (0)

/* ---- timed region: the kernel only --------------------------------------- */
static struct timespec pb_t0;
static void pb_timer_start(void)
{
  clock_gettime(CLOCK_MONOTONIC, &pb_t0);
}
static void pb_timer_stop(void)
{
  struct timespec t1;
  clock_gettime(CLOCK_MONOTONIC, &t1);
  fprintf(stderr, "DP_TIMED_REGION_SECONDS %.9f\n",
          (double)(t1.tv_sec - pb_t0.tv_sec) + 1e-9 * (double)(t1.tv_nsec - pb_t0.tv_nsec));
}

/* ---- the program under study -------------------------------------------- */
static double a[N];
static double c[N];

static void init_array(void)
{
  int i;
  for (i = 0; i < N; i++) a[i] = (double)(i % 251) * 0.02;
}

static void kernel_prefix(double* a, double* c)
{
  int r;
  const int n = N;
  const int bs = 4096;
  const int nb = (n + bs - 1) / bs;
  double* blockSum = (double*)malloc((size_t)nb * sizeof(double));

  for (r = 0; r < R; r++) {
    int b;

    /* Pass 1: each block computes its own local prefix sum, starting
       fresh from a[start]; the true carry-in from earlier blocks is
       added in pass 3. Blocks touch disjoint ranges of c, so there is
       no loop-carried dependence across b. */
    #pragma omp parallel for private(b) shared(a, c, blockSum) firstprivate(n, nb) schedule(static)
    for (b = 0; b < nb; b++) {
      int start = b * bs;
      int end = (start + bs < n) ? (start + bs) : n;
      int i;
      double acc = a[start];
      c[start] = acc;
      for (i = start + 1; i < end; i++) {
        acc += a[i];
        c[i] = acc;
      }
      blockSum[b] = acc;
    }

    /* Pass 2: turn per-block totals into exclusive prefix offsets.
       Sequential but O(nb), a small constant-factor addition, not an
       O(N) recomputation. */
    {
      double running = 0.0;
      int b2;
      for (b2 = 0; b2 < nb; b2++) {
        double s = blockSum[b2];
        blockSum[b2] = running;
        running += s;
      }
    }

    /* Pass 3: add each block's carry-in offset to its own elements.
       Disjoint ranges again, so blocks are independent; block 0's
       offset is 0 and needs no update. */
    #pragma omp parallel for private(b) shared(c, blockSum) firstprivate(n, nb) schedule(static)
    for (b = 1; b < nb; b++) {
      int start = b * bs;
      int end = (start + bs < n) ? (start + bs) : n;
      int i;
      double off = blockSum[b];
      for (i = start; i < end; i++)
        c[i] += off;
    }
  }

  free(blockSum);
}

int main(int argc, char** argv)
{
  int i;
  init_array();

  /* Optional perturbed input, see PB_PERTURB. */
  if (argc > 1)
    {
      unsigned long long pb_state = pb_seed(argv[1]);
      PB_PERTURB(a, N);
    }

  pb_timer_start();
  kernel_prefix(a, c);
  pb_timer_stop();

  for (i = 0; i < N; i += (N / 512 > 0 ? N / 512 : 1)) pb_emit(c[i]);

  pb_report();
  return 0;
}
